#!/usr/bin/env bash
# Driver for the luna-max-v4 campaign: 3 tasks x 2 trials = 6 Codex takers,
# gpt-5.6-luna at effort max, at most 3 in flight.
#
# Per sandbox it writes:
#   _codex_final.md    Codex's final message (wrapper stdout)
#   _codex_stderr.log  the whole transcript incl. the "tokens used" block
#   _rc                "<rc> <wall_seconds>"
#   _done              marker
# and finally results/luna-max-v4/_ALLDONE when every run has finished.
#
# Run `python run.py setup` first. Do not edit this file.
set -u

ROOT=/c/Users/slb/ollama-bench/results/luna-max-v4
CODEXRUN=$HOME/.claude/skills/codex-run/scripts/codex-run
TASKS="56_tmpl 57_stateful 55_minilang"
TRIALS=2
MAXPAR=3

rm -f "$ROOT/_ALLDONE"

one() {
    sb=$1
    cd "$sb" || return
    # Resume-safe: a sandbox that already finished is left alone, so the driver
    # can be relaunched if its shell was killed.
    if [ -f "$sb/_done" ]; then echo "skip $sb (already done)"; return; fi
    t0=$(date +%s)
    bash "$CODEXRUN" --model gpt-5.6-luna --effort max --cwd "$sb" \
        --timeout 1800 --ephemeral "$(cat "$sb/TASK.md")" \
        > "$sb/_codex_final.md" 2> "$sb/_codex_stderr.log"
    rc=$?
    t1=$(date +%s)
    printf '%d %d\n' "$rc" "$((t1 - t0))" > "$sb/_rc"
    touch "$sb/_done"
    echo "done $sb rc=$rc wall=$((t1 - t0))s"
}

n=0
for task in $TASKS; do
    for k in $(seq 1 $TRIALS); do
        sb="$ROOT/$task/t$k"
        one "$sb" &
        n=$((n + 1))
        while [ "$(jobs -pr | wc -l)" -ge "$MAXPAR" ]; do sleep 5; done
    done
done
wait
echo "all $n runs finished"
date -Is > "$ROOT/_ALLDONE"
